SELECT toInt64(toStartOfInterval(time_bucket, toIntervalSecond(?))) * 1000000000 AS bucket_time_unix_nano, if(user_email != '', user_email, hook_hostname) AS group_value, sumIfMerge(total_cost) AS m_cost_usd, sumIfMerge(total_input_tokens) AS m_input_tokens, sumIfMerge(total_output_tokens) AS m_output_tokens, sumIfMerge(total_tokens) AS m_tokens_total, sumIfMerge(cache_read_input_tokens) AS m_cache_read_tokens, sumIfMerge(cache_creation_input_tokens) AS m_cache_write_tokens, if(uniqExactIfMerge(unique_tool_calls) = 0, countIfMerge(total_tool_calls), uniqExactIfMerge(unique_tool_calls)) AS m_tool_calls, uniqExactIfMerge(total_chats) AS m_chats, sumIfMerge(total_work_units) AS m_total_work_units, sumIfMerge(scored_cost) AS m_scored_cost, sumIfMerge(scored_tokens) AS m_scored_tokens FROM attribute_metrics_summaries WHERE is_active = 1 AND gram_project_id IN (?) AND time_bucket >= toStartOfHour(fromUnixTimestamp64Nano(?)) AND time_bucket <= toStartOfHour(fromUnixTimestamp64Nano(?)) GROUP BY bucket_time_unix_nano, group_value
